/**
 * What HeroSplit shows under the lead: three figures in cards, a row of faces with a proof line, two small
 * feature cards, or a quote with its author over three figures.
 */
import { For, type JSX } from "solid-js";
import { Box } from "../primitives/box/box";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { FigureBlock } from "../components/figure-block";
import { MediaFrame } from "../components/media-frame";
import type { HeroContent } from "../blocks/hero-split.types";

export type HeroSplitExtrasProps = {
  content: HeroContent;
  extra?: "stats" | "avatars" | "minis" | "quote" | "none";
};

export function HeroSplitExtras({ content, extra = "none" }: HeroSplitExtrasProps) {
  return (
    <>
      {((extra as string) === "stats") ? (
        <Box class="grid grid-cols-3 gap-4" data-testid="hero-stats">
          <For each={content.stats ?? []}>{(s, iOf) => { const i = iOf(); return (
            <>
              {(i < 3) ? (
                <Stack gap="0" class="rounded bg-card inset-ring inset-ring-border p-4" data-testid="hero-stat">
                  <Text size="2xl" weight="semibold">
                    {s.value}
                  </Text>
                  <Text size="xs" class="text-muted-foreground">
                    {s.label}
                  </Text>
                </Stack>
              ) : null}
            </>
          ); }}</For>
        </Box>
      ) : null}
      {((extra as string) === "avatars") ? (
        <Group gap="4" align="center" class="flex-wrap" data-testid="hero-proof">
          <Group gap="2" align="center">
            <For each={content.people ?? []}>{(p, iOf) => { const i = iOf(); return (
              <>
                {(i < 4) ? (
                  <MediaFrame alt={p.author} ratio="1/1" class="size-10 shrink-0 rounded-full" />
                ) : null}
              </>
            ); }}</For>
          </Group>
          <Text size="sm" class="text-muted-foreground">
            {content.proof}
          </Text>
        </Group>
      ) : null}
      {((extra as string) === "minis") ? (
        <Box class="grid grid-cols-1 gap-4 sm:grid-cols-2" data-testid="hero-minis">
          <For each={content.features ?? []}>{(f, iOf) => { const i = iOf(); return (
            <>
              {(i < 2) ? (
                <Group gap="4" align="start" class="rounded bg-card inset-ring inset-ring-border p-4" data-testid="hero-mini">
                  <Box class="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
                    <LucideIcon name={f.icon} size={20} />
                  </Box>
                  <Stack gap="0">
                    <Text size="sm" weight="semibold">
                      {f.title}
                    </Text>
                    <Text size="xs" class="text-muted-foreground">
                      {f.text}
                    </Text>
                  </Stack>
                </Group>
              ) : null}
            </>
          ); }}</For>
        </Box>
      ) : null}
      {((extra as string) === "quote") ? (
        <Stack gap="6" align="stretch">
          <For each={content.people ?? []}>{(p, iOf) => { const i = iOf(); return (
            <>
              {(i < 1) ? (
                <FigureBlock class="flex flex-col gap-4" testid="hero-quote">
                  <Text tag="blockquote" class="text-lg font-medium">
                    {p.quote}
                  </Text>
                  <Group gap="4" align="center">
                    <MediaFrame alt={p.author} ratio="1/1" class="size-10 shrink-0 rounded-full" />
                    <Stack gap="0">
                      <Text size="sm" weight="semibold">
                        {p.author}
                      </Text>
                      <Text size="xs" class="text-muted-foreground">
                        {p.role}
                      </Text>
                    </Stack>
                  </Group>
                </FigureBlock>
              ) : null}
            </>
          ); }}</For>
          <Box class="grid grid-cols-3 gap-4" data-testid="hero-stats">
            <For each={content.stats ?? []}>{(s, iOf) => { const i = iOf(); return (
              <>
                {(i < 3) ? (
                  <Stack gap="0" class="rounded bg-card inset-ring inset-ring-border p-4" data-testid="hero-stat">
                    <Text size="2xl" weight="semibold">
                      {s.value}
                    </Text>
                    <Text size="xs" class="text-muted-foreground">
                      {s.label}
                    </Text>
                  </Stack>
                ) : null}
              </>
            ); }}</For>
          </Box>
        </Stack>
      ) : null}
    </>
  );
}
